%% UFACTORY Lite 6 - Random Forward Kinematics Exercise
clear; clc; close all;

syms q1 q2 q3 q4 q5 q6 real

%% DH Parameters (mm → m)
d1 = 243.3; d2 = 0; d3 = 0; d4 = 227.6; d5 = 0; d6 = 61.5;
a1 = 0; a2 = 200; a3 = 87; a4 = 0; a5 = 0; a6 = 0;

alpha1 = -90; alpha2 = 180; alpha3 = 90;
alpha4 = 90; alpha5 = -90; alpha6 = 0;

%% Random "reasonable" joint angles (deg)
%% Random "reasonable" joint angles (deg) - collision reduced

q = [ ...
    randi([-90 90]), ...     % q1 (base full range OK)
    randi([-45 45]), ...     % q2 (LIMITED shoulder → avoids base collision)
    randi([-45 45]), ...     % q3 (LIMITED elbow → avoids self-collision)
    randi([-180 180]), ...   % q4
    randi([-120 120]), ...   % q5 (slightly constrained wrist pitch)
    randi([-180 180])        % q6
];

q1v = q(1);
q2v = q(2);
q3v = q(3);
q4v = q(4);
q5v = q(5);
q6v = q(6);

fprintf("Random joint angles (deg):\n");
disp(q);

%% Apply joint offsets (IMPORTANT from your model)
theta1 = q1v;
theta2 = q2v - 90;
theta3 = q3v - 90;
theta4 = q4v;
theta5 = q5v;
theta6 = q6v;

%% Homogeneous transforms
T01 = dh(theta1,d1,alpha1,a1);
T12 = dh(theta2,d2,alpha2,a2);
T23 = dh(theta3,d3,alpha3,a3);
T34 = dh(theta4,d4,alpha4,a4);
T45 = dh(theta5,d5,alpha5,a5);
T56 = dh(theta6,d6,alpha6,a6);

%% Forward kinematics
T = T01*T12*T23*T34*T45*T56;
T = double(T);

%% Extract position
p = T(1:3,4);

fprintf("End-effector position (m):\n");
disp(p);

fprintf("End-effector position (mm):\n");
disp(p*1000);

%% Local DH function

function T = dh(theta_deg, d_mm, alpha_deg, a_mm)

T = [cosd(theta_deg), -sind(theta_deg)*cosd(alpha_deg),  sind(theta_deg)*sind(alpha_deg), a_mm/1000*cosd(theta_deg);
     sind(theta_deg),  cosd(theta_deg)*cosd(alpha_deg), -cosd(theta_deg)*sind(alpha_deg), a_mm/1000*sind(theta_deg);
     0,                sind(alpha_deg),                 cosd(alpha_deg),                 d_mm/1000;
     0,                0,                                0,                                1];
end
